    /// <summary>Satiety a survivor burns through in a day.</summary>
    public static double DAILY_SATIETY = Time.DAY_LENGTH;

    /// <summary>Within this of a survivor, zombies count as "at the colony".</summary>
    public const int NEAR = 25;

    /// <summary>Days the colony's food (raw and hot) would last at the current headcount.</summary>
    public static double foodDays(SimState state)
    {
        var people = Expeditions.everyone(state).length;
        if (people == 0)
        {
            return double.PositiveInfinity;
        }
        var satiety = state.items.reduce((sum, i) => sum + ((i.kind == "food") ? Food.MEAL_VALUE : ((i.kind == "meal") ? Food.HOT_MEAL_VALUE : 0)), 0.0);
        return ((double)(satiety) / ((people * DAILY_SATIETY)));
    }

    /// <summary>Days until winter starts (0 in winter).</summary>
    public static double daysToWinter(int tick)
    {
        var day = Time.dayOf(tick);
        var intoYear = (day - 1) % (4 * Seasons.SEASON_DAYS);
        return (Seasons.seasonOf(tick) == "winter") ? 0 : ((3 * Seasons.SEASON_DAYS) - intoYear);
    }
    public static double daysToWinter(double tick) => daysToWinter((int)tick);

    public static List<Alert> alerts(SimState state)
    {
        List<Alert> @out = [];
        /*TODO return type*/object add(string level, string text, Point? at = default)
